import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  // --- ESTADOS DE CONTROL ---
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [seccionActual, setSeccionActual] = useState('inventario'); // 'inventario', 'crear', 'ganancias'

  // --- ESTADOS DE DATOS ---
  const [productos, setProductos] = useState([]);
  const [ventas, setVentas] = useState([]);
  const [nuevoProducto, setNuevoProducto] = useState({ 
    nombre: '', categoria: '', precioCompra: '', iva: 19, precioVenta: '', stockActual: '', imagenUrl: '' 
  });

  useEffect(() => {
    if (isLoggedIn) {
      cargarDatos();
    }
  }, [isLoggedIn]);

  const cargarDatos = async () => {
    try {
      const resProd = await axios.get('http://localhost:8080/api/productos');
      setProductos(resProd.data || []);
      const resVent = await axios.get('http://localhost:8080/api/ventas');
      setVentas(resVent.data || []);
    } catch (err) { 
      console.error("Error al cargar la base de datos", err); 
    }
  };

  // --- LÓGICA DE CONTROL DE ACCESO (LOGIN ÚNICO) ---
  const manejarLogin = (e) => {
    e.preventDefault();
    if (username === 'admin' && password === '12345') {
      setIsLoggedIn(true);
    } else {
      alert('⚠️ Credenciales incorrectas. Solo el administrador tiene acceso.');
    }
  };

  const manejarVenta = async (id) => {
    try {
      await axios.post(`http://localhost:8080/api/ventas/${id}/1`);
      cargarDatos();
    } catch (err) { 
      alert("⚠️ Stock Agotado o error en el servidor."); 
    }
  };

  const guardarProducto = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://localhost:8080/api/productos', nuevoProducto);
      setNuevoProducto({ nombre: '', categoria: '', precioCompra: '', iva: 19, precioVenta: '', stockActual: '', imagenUrl: '' });
      alert("✅ Producto guardado permanentemente en PostgreSQL");
      cargarDatos();
      setSeccionActual('inventario'); // Te regresa a ver el inventario
    } catch (err) { 
      alert("Error al conectar con el servidor de Java."); 
    }
  };

  // --- CÁLCULO DE IVA AUTOMÁTICO PARA EL DISTRIBUIDOR ---
  const sugerirPrecioVenta = (costo, ivaPorcentaje) => {
    if (!costo) return 0;
    const porcentaje = ivaPorcentaje || 0;
    const costoConIva = costo * (1 + (porcentaje / 100));
    return Math.round(costoConIva * 1.30); // Sugiere un 30% de margen de ganancia estándar
  };

  // --- REPORTES FINANCIEROS (CON CONTROL DE NULOS) ---
  const ingresosBrutos = ventas.reduce((acc, v) => acc + (v.total || 0), 0);
  const gananciaNeta = ventas.reduce((acc, v) => {
    const p = productos.find(prod => prod.nombre === v.productoNombre);
    if (p && p.precioCompra !== null && p.precioCompra !== undefined) {
      const porcentajeIva = p.iva || 0;
      const costoConIva = p.precioCompra * (1 + (porcentajeIva / 100));
      return acc + ((v.total || 0) - (costoConIva * (v.cantidad || 1)));
    }
    return acc + (v.total || 0); // Si no encuentra el producto o costo, asume la venta como bruto temporalmente
  }, 0);

  // --- DISEÑO DE ESTILOS EN MODO DARK PREMIUM ---
  const s = {
    loginPage: { display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100vh', backgroundColor: '#0f0a06', color: '#d4a373', fontFamily: 'sans-serif' },
    loginCard: { backgroundColor: '#1e160e', padding: '40px', borderRadius: '15px', border: '1px solid #d4a373', textAlign: 'center', width: '320px' },
    input: { backgroundColor: '#0f0a06', color: '#fff', border: '1px solid #d4a373', padding: '12px', borderRadius: '8px', marginBottom: '15px', width: '90%' },
    btn: { backgroundColor: '#d4a373', color: '#1e160e', padding: '12px', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', width: '100%' },
    navBar: { display: 'flex', gap: '15px', padding: '20px', backgroundColor: '#1e160e', borderBottom: '2px solid #3c2a1a', justifyContent: 'center' },
    navBtn: (active) => ({ backgroundColor: active ? '#d4a373' : 'transparent', color: active ? '#1e160e' : '#d4a373', border: '1px solid #d4a373', padding: '10px 20px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }),
    grid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(250px, 1fr))', gap: '25px', padding: '30px' },
    prodCard: { backgroundColor: '#1e160e', borderRadius: '15px', border: '1px solid #3c2a1a', overflow: 'hidden', textAlign: 'center', paddingBottom: '15px' }
  };

  // ==================== VISTA 1: LOGIN ====================
  if (!isLoggedIn) {
    return (
      <div style={s.loginPage}>
        <div style={s.loginCard}>
          <h2 style={{margin: '0 0 20px 0'}}>☕ EL PAISITA UP</h2>
          <p style={{color: '#8b735b', fontSize: '0.9rem', marginBottom: '20px'}}>SISTEMA ADMINISTRATIVO</p>
          <form onSubmit={manejarLogin}>
            <input style={s.input} placeholder="Usuario" value={username} onChange={e => setUsername(e.target.value)} required />
            <input style={s.input} type="password" placeholder="Contraseña" value={password} onChange={e => setPassword(e.target.value)} required />
            <button type="submit" style={s.btn}>ENTRAR AL PANEL</button>
          </form>
        </div>
      </div>
    );
  }

  // ==================== VISTA 2: PANEL DE ADMINISTRADOR ====================
  return (
    <div style={{ backgroundColor: '#0f0a06', color: '#fff', minHeight: '100vh', fontFamily: 'sans-serif' }}>
      {/* MENÚ POR APARTADOS */}
      <div style={s.navBar}>
        <button style={s.navBtn(seccionActual === 'inventario')} onClick={() => setSeccionActual('inventario')}>📦 Ver Inventario</button>
        <button style={s.navBtn(seccionActual === 'crear')} onClick={() => setSeccionActual('crear')}>➕ Añadir Producto</button>
        <button style={s.navBtn(seccionActual === 'ganancias')} onClick={() => setSeccionActual('ganancias')}>📊 Cuadro de Ganancias</button>
        <button style={{...s.navBtn(false), borderColor: '#ff4d4d', color: '#ff4d4d'}} onClick={() => setIsLoggedIn(false)}>🚪 Salir</button>
      </div>

      {/* APARTADO: VER INVENTARIO EN TARJETAS CON IMAGEN */}
      {seccionActual === 'inventario' && (
        <div>
          <h2 style={{ textAlign: 'center', color: '#d4a373', marginTop: '30px' }}>Catálogo de Cafetería</h2>
          <div style={s.grid}>
            {productos.map(p => (
              <div key={p.id} style={s.prodCard}>
                <img src={p.imagenUrl || 'https://images.unsplash.com/photo-1509042239860-f550ce710b93?q=80&w=500'} alt={p.nombre} style={{ width: '100%', height: '150px', objectFit: 'cover' }} />
                <h3 style={{ color: '#d4a373', margin: '15px 0 5px 0' }}>{p.nombre}</h3>
                <p style={{ color: '#aaa', margin: '0 0 10px 0' }}>Stock: <b style={{color: (p.stockActual || 0) < 5 ? '#ff4d4d' : '#4CAF50'}}>{p.stockActual || 0} u</b></p>
                <h4 style={{ margin: '0 0 15px 0' }}>${(p.precioVenta || 0).toLocaleString()} COP</h4>
                <button style={{...s.btn, width: '80%'}} onClick={() => manejarVenta(p.id)}>VENDER 1</button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* APARTADO: REGISTRO FINANCIERO CON IVA */}
      {seccionActual === 'crear' && (
        <div style={{ display: 'flex', justifyContent: 'center', marginTop: '40px' }}>
          <div style={{ backgroundColor: '#1e160e', padding: '30px', borderRadius: '15px', border: '1px solid #d4a373', width: '450px' }}>
            <h2 style={{ marginTop: 0, color: '#d4a373' }}>Ingreso de Mercancía (Distribuidor)</h2>
            <form onSubmit={guardarProducto}>
              <input style={s.input} placeholder="Nombre del Producto (Ej: Empanada)" value={nuevoProducto.nombre} onChange={e => setNuevoProducto({...nuevoProducto, nombre: e.target.value})} required />
              <input style={s.input} placeholder="Categoría" value={nuevoProducto.categoria} onChange={e => setNuevoProducto({...nuevoProducto, categoria: e.target.value})} required />
              <input style={s.input} placeholder="URL de la Imagen en Internet" value={nuevoProducto.imagenUrl} onChange={e => setNuevoProducto({...nuevoProducto, imagenUrl: e.target.value})} />

              <div style={{ display: 'flex', gap: '10px' }}>
                <input style={s.input} type="number" placeholder="Costo Distribuidor ($)" value={nuevoProducto.precioCompra} onChange={e => setNuevoProducto({...nuevoProducto, precioCompra: parseFloat(e.target.value) || ''})} required />
                <select style={s.input} value={nuevoProducto.iva} onChange={e => setNuevoProducto({...nuevoProducto, iva: parseFloat(e.target.value)})}>
                  <option value="0">IVA 0% (Exento)</option>
                  <option value="5">IVA 5%</option>
                  <option value="19">IVA 19% (General CO)</option>
                </select>
              </div>

              {/* MUESTRA EL PRECIO SUGERIDO EN TIEMPO REAL CON IVA */}
              <div style={{ backgroundColor: '#2c1e12', padding: '12px', borderRadius: '8px', marginBottom: '15px', border: '1px dashed #d4a373' }}>
                <p style={{ margin: 0, fontSize: '0.9rem', color: '#aaa' }}>
                  Costo con IVA + Margen Sugerido (30%): 
                  <b style={{ color: '#4CAF50', marginLeft: '5px' }}>
                    ${sugerirPrecioVenta(nuevoProducto.precioCompra, nuevoProducto.iva).toLocaleString()} COP
                  </b>
                </p>
              </div>

              <input style={s.input} type="number" placeholder="Precio Final de Venta Establecido ($)" value={nuevoProducto.precioVenta} onChange={e => setNuevoProducto({...nuevoProducto, precioVenta: parseFloat(e.target.value) || ''})} required />
              <input style={s.input} type="number" placeholder="Cantidad que llegó (Stock)" value={nuevoProducto.stockActual} onChange={e => setNuevoProducto({...nuevoProducto, stockActual: parseInt(e.target.value) || ''})} required />

              <button type="submit" style={{...s.btn, backgroundColor: '#4CAF50', color: '#fff'}}>METER A LA BASE DE DATOS</button>
            </form>
          </div>
        </div>
      )}

      {/* APARTADO: CONTROL DE UTILIDADES */}
      {seccionActual === 'ganancias' && (
        <div style={{ padding: '40px', maxWidth: '800px', margin: '0 auto' }}>
          <h2 style={{ color: '#d4a373', textAlign: 'center' }}>📈 Balance y Reporte de Caja</h2>
          <div style={{ display: 'flex', gap: '20px', marginTop: '30px' }}>
            <div style={{ flex: 1, backgroundColor: '#1e160e', padding: '25px', borderRadius: '15px', border: '1px solid #3c2a1a', textAlign: 'center' }}>
              <h3>Caja Total (Bruto)</h3>
              <h2 style={{ color: '#fff' }}>${ingresosBrutos.toLocaleString('es-CO')} COP</h2>
            </div>
            <div style={{ flex: 1, backgroundColor: '#1e160e', padding: '25px', borderRadius: '15px', border: '1px solid #4CAF50', textAlign: 'center' }}>
              <h3 style={{ color: '#4CAF50' }}>Utilidad Neta Libre</h3>
              <h2>${gananciaNeta.toLocaleString('es-CO')} COP</h2>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
